import{_ as o,C as n,o as a,c as i,j as e,a as l,E as r,a2 as c}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"AnvilLib dev/26.1 分支概览","description":"","frontmatter":{},"headers":[],"relativePath":"26.1/index.md","filePath":"26.1/index.md"}'),s={name:"26.1/index.md"};function g(f,t,x,y,v,b){const d=n("BranchContextCard");return a(),i("div",null,[t[0]||(t[0]=e("h1",{id:"anvillib-dev-26-1-分支概览",tabindex:"-1"},[l("AnvilLib "),e("code",null,"dev/26.1"),l(" 分支概览 "),e("a",{class:"header-anchor",href:"#anvillib-dev-26-1-分支概览","aria-label":'Permalink to "AnvilLib `dev/26.1` 分支概览"'},"​")],-1)),r(d,{branch:"26.1"}),t[1]||(t[1]=c('<p>本篇文档对应 <code>AnvilLib</code> 的 <code>dev/26.1</code> 分支，面向 <strong>Minecraft 26.1.2</strong>、<strong>NeoForge 26.1.2.x</strong> 与 <strong>Java 25</strong> 开发环境。本分支下的所有代码示例、类路径（例如 <code>net.minecraft.resources.Identifier</code>、<code>GuiGraphicsExtractor</code> 等 26.1 命名）与 Maven 坐标均严格对齐 <code>dev/26.1</code> 源码。</p><hr><h2 id="环境与构建基线" tabindex="-1">环境与构建基线 <a class="header-anchor" href="#环境与构建基线" aria-label="Permalink to &quot;环境与构建基线&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">配置项</th><th style="text-align:left;"><code>dev/26.1</code> 要求</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>JDK 版本</strong></td><td style="text-align:left;">Java 25 (<code>java_version=25</code>)</td></tr><tr><td style="text-align:left;"><strong>Minecraft 版本范围</strong></td><td style="text-align:left;"><code>[26.1, 26.2)</code>（开发环境基于 <code>26.1.2</code>）</td></tr><tr><td style="text-align:left;"><strong>NeoForge 版本范围</strong></td><td style="text-align:left;"><code>[21,)</code>（开发环境基于 <code>26.1.2.x</code>）</td></tr><tr><td style="text-align:left;"><strong>Loader 版本范围</strong></td><td style="text-align:left;"><code>[4,)</code></td></tr><tr><td style="text-align:left;"><strong>Maven GroupId</strong></td><td style="text-align:left;"><code>dev.anvilcraft.lib</code></td></tr><tr><td style="text-align:left;"><strong>聚合模块 ArtifactId</strong></td><td style="text-align:left;"><code>anvillib-neoforge-26.1</code></td></tr><tr><td style="text-align:left;"><strong>当前工程版本 (<code>mod_version</code>)</strong></td><td style="text-align:left;"><code>2.0.0</code></td></tr></tbody></table><hr><h2 id="模块矩阵-dev-26-1" tabindex="-1">模块矩阵（<code>dev/26.1</code>） <a class="header-anchor" href="#模块矩阵-dev-26-1" aria-label="Permalink to &quot;模块矩阵（`dev/26.1`）&quot;">​</a></h2><p><code>AnvilLib</code> 在 <code>dev/26.1</code> 分支下共提供 <strong>1 个聚合发行模块 (<code>main</code>)</strong> 与 <strong>20 个独立功能子模块</strong>（另含 1 个内部测试模块 <code>test</code> 与 1 个内部调试模块 <code>renderdoc-loader</code>）：</p><table tabindex="0"><thead><tr><th style="text-align:left;">模块名称</th><th style="text-align:left;">ArtifactId (<code>dev.anvilcraft.lib</code>)</th><th style="text-align:left;">根包名</th><th style="text-align:center;">接口注入数据</th><th style="text-align:left;">核心职责与适用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="./getting-started.html">Main（聚合包）</a></strong></td><td style="text-align:left;"><code>anvillib-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2</code></td><td style="text-align:center;">聚合透传</td><td style="text-align:left;">打包并重导出全部 20 个运行时功能子模块</td></tr><tr><td style="text-align:left;"><strong><a href="./codec/">Codec</a></strong></td><td style="text-align:left;"><code>anvillib-codec-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.codec</code></td><td style="text-align:center;">否</td><td style="text-align:left;"><code>Codec</code> / <code>MapCodec</code> / <code>StreamCodec</code> 预置常量、1~16 参数构建代理与原版谓词流编解码</td></tr><tr><td style="text-align:left;"><strong><a href="./collision/">Collision</a></strong></td><td style="text-align:left;"><code>anvillib-collision-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.collision</code></td><td style="text-align:center;">否</td><td style="text-align:left;">基于 13 轴 SAT（分离轴定理）的 AABB 与三角形网格静态碰撞、三轴独立扫掠与真扫掠碰撞计算</td></tr><tr><td style="text-align:left;"><strong><a href="./config/">Config</a></strong></td><td style="text-align:left;"><code>anvillib-config-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.config</code></td><td style="text-align:center;">否</td><td style="text-align:left;">注解驱动配置声明、数值范围/滑块约束、嵌套折叠对象、半透明侧栏配置 GUI 与语言数据生成</td></tr><tr><td style="text-align:left;"><strong><a href="./cube/">Cube</a></strong></td><td style="text-align:left;"><code>anvillib-cube-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.cube</code></td><td style="text-align:center;">否</td><td style="text-align:left;">模型斜棱线描边高亮、BVH 精确射线拾取、动态部件拾取提供器与运行时黑名单排除</td></tr><tr><td style="text-align:left;"><strong><a href="./explosion/">Explosion</a></strong></td><td style="text-align:left;"><code>anvillib-explosion-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.explosion</code></td><td style="text-align:center;">否</td><td style="text-align:left;">批量爆炸会话 (<code>ExplosionSession</code>) 与自定义爆炸执行器 (<code>ExplosionExecutor</code>)</td></tr><tr><td style="text-align:left;"><strong><a href="./font/">Font</a></strong></td><td style="text-align:left;"><code>anvillib-font-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.font</code></td><td style="text-align:center;"><strong>是</strong></td><td style="text-align:left;">客户端 TrueType 字体管理、多通道/单通道 SDF 字形图集与 <code>GuiGraphicsExtractor</code> 扩展</td></tr><tr><td style="text-align:left;"><strong><a href="./integration/">Integration</a></strong></td><td style="text-align:left;"><code>anvillib-integration-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.integration</code></td><td style="text-align:center;">否</td><td style="text-align:left;">基于 <code>@Integration</code> 注解的外部模组存在性、版本范围与物理端条件加载框架</td></tr><tr><td style="text-align:left;"><strong><a href="./math/">Math</a></strong></td><td style="text-align:left;"><code>anvillib-math-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.math</code></td><td style="text-align:center;">否</td><td style="text-align:left;">可序列化数学表达式树、Flat 文本双向解析与自校验回写、变参自定义函数与双注册表</td></tr><tr><td style="text-align:left;"><strong><a href="./moveable-entity-block/">Moveable Entity Block</a></strong></td><td style="text-align:left;"><code>anvillib-moveable-entity-block-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.piston</code></td><td style="text-align:center;"><strong>是</strong></td><td style="text-align:left;">允许带 <code>BlockEntity</code> 的方块被活塞推动并保留 NBT 状态与移动渲染数据</td></tr><tr><td style="text-align:left;"><strong><a href="./multiblock/">Multiblock</a></strong></td><td style="text-align:left;"><code>anvillib-multiblock-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.multiblock</code></td><td style="text-align:center;">否</td><td style="text-align:left;">数据驱动的动态多方块结构定义、控制器注册、成形/解体状态管理与网络同步</td></tr><tr><td style="text-align:left;"><strong><a href="./network/">Network</a></strong></td><td style="text-align:left;"><code>anvillib-network-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.network</code></td><td style="text-align:center;">否</td><td style="text-align:left;">面向 <code>PLAY</code> / <code>CONFIGURATION</code> / <code>COMMON</code> 阶段的数据包方向接口与 <code>@Network</code> 自动扫描注册</td></tr><tr><td style="text-align:left;"><strong><a href="./recipe/">Recipe</a></strong></td><td style="text-align:left;"><code>anvillib-recipe-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.recipe</code></td><td style="text-align:center;"><strong>是</strong></td><td style="text-align:left;">世界内配方系统：Trigger 触发器、方块/物品/实体 Predicate、Outcome 产出与 <code>ItemBatchPlan</code> 容量受限批次规划</td></tr><tr><td style="text-align:left;"><strong><a href="./registrum/">Registrum</a></strong></td><td style="text-align:left;"><code>anvillib-registrum-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.registrum</code></td><td style="text-align:center;">否</td><td style="text-align:left;">链式注册与 Datagen 联动框架，覆盖方块、物品、创造标签页变体选择器、实体、流体、组件与附件等</td></tr><tr><td style="text-align:left;"><strong><a href="./rendering/">Rendering</a></strong></td><td style="text-align:left;"><code>anvillib-rendering-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.rendering</code></td><td style="text-align:center;">否</td><td style="text-align:left;">Blaze3D 计算着色器与无绑定纹理扩展、Bloom/Blur/Glitch 后处理、CachedBER、Hi-Z 遮挡剔除、结构投影、2D SDF 与 GUI PiP</td></tr><tr><td style="text-align:left;"><strong><a href="./rpc/">RPC</a></strong></td><td style="text-align:left;"><code>anvillib-rpc-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.rpc</code></td><td style="text-align:center;">否</td><td style="text-align:left;">基于 <code>@RemoteCallable</code> 与方法引用的跨端远程过程调用、返回值异步回调与参数校验框架</td></tr><tr><td style="text-align:left;"><strong><a href="./space-select/">Space Select</a></strong></td><td style="text-align:left;"><code>anvillib-space-select-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.space_select</code></td><td style="text-align:center;">否</td><td style="text-align:left;">三维选区 (<code>District</code>) 管理、选区工具物品、客户端滚轮缩放与线框渲染</td></tr><tr><td style="text-align:left;"><strong><a href="./sync/">Sync</a></strong></td><td style="text-align:left;"><code>anvillib-sync-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.sync</code></td><td style="text-align:center;">否</td><td style="text-align:left;">基于 <code>@Sync</code> / <code>@LazySync</code> 注解与编译期字节码注入 (<code>anvillib-sync-processor-neoforge-26.1</code>) 的字段自动同步</td></tr><tr><td style="text-align:left;"><strong><a href="./ui/">UI</a></strong></td><td style="text-align:left;"><code>anvillib-ui-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.ui</code></td><td style="text-align:center;">否</td><td style="text-align:left;">九宫格/三切片柔性控件渲染库：支持亮/暗主题、五态交互变体、透明度、指针箭头、按钮与弹出层</td></tr><tr><td style="text-align:left;"><strong><a href="./util/">Util</a></strong></td><td style="text-align:left;"><code>anvillib-util-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.util</code></td><td style="text-align:center;">否</td><td style="text-align:left;">集合/数学/体素形状/物品栏工具、<code>FlattenLoop</code> 多维循环扁平化、组件信息封装、谓词模型与 <code>UnlimitedItemStack</code></td></tr><tr><td style="text-align:left;"><strong><a href="./wheel/">Wheel</a></strong></td><td style="text-align:left;"><code>anvillib-wheel-neoforge-26.1</code></td><td style="text-align:left;"><code>dev.anvilcraft.lib.v2.wheel</code></td><td style="text-align:center;">否</td><td style="text-align:left;">客户端轮盘菜单 API：支持 <code>TAP</code> / <code>HOLD</code> 模式、自动分页、子菜单跳转与毛玻璃圆盘渲染</td></tr></tbody></table>',8))])}const m=o(s,[["render",g]]);export{p as __pageData,m as default};
